USE accessflow;
ALTER TABLE users MODIFY COLUMN role ENUM('student','admin','security','teacher') NOT NULL DEFAULT 'student', ADD COLUMN roll_no VARCHAR(40) NULL, ADD COLUMN course VARCHAR(80) NULL, ADD COLUMN branch VARCHAR(80) NULL, ADD COLUMN section VARCHAR(20) NULL, ADD COLUMN phone VARCHAR(20) NULL, ADD COLUMN photo_url LONGTEXT NULL;
CREATE TABLE IF NOT EXISTS campus_attendance (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, pass_id INT NOT NULL, attendance_date DATE NOT NULL, gate_entry_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, status ENUM('Present') NOT NULL DEFAULT 'Present', UNIQUE KEY unique_student_day (student_id, attendance_date), FOREIGN KEY (student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY (pass_id) REFERENCES passes(id) ON DELETE CASCADE);
